class Storage {
  constructor() {
    this.store = {};
  }
  set(key, val) {
    this.store[key] = JSON.stringify(val);
  }
  get(key) {
    try { return JSON.parse(this.store[key] ?? null); }
    catch { return null; }
  }
  remove(key) { delete this.store[key]; }
}
const store = new Storage();
store.set("config", { theme: "dark" });
console.log(store.get("config"));

